6.3 Generate Space-Time Cube

library(Kendall)

hex_trend &lt;- hex_time_trips %&gt;%
  group_by(HEX_ID) %&gt;%
  summarise(
    mk_tau = tryCatch({
      if(n() &gt;= 3) Kendall(trips_sum)$tau else NA_real_
    }, error = function(e) NA_real_),
    mk_p = tryCatch({
      if(n() &gt;= 3) Kendall(trips_sum)$sl else NA_real_
    }, error = function(e) NA_real_),
    .groups = "drop"
  )

2.3 Geocoding HDB resale data

Importing HDB data

HDBresale &lt;- read_csv(
  "data/rawdata/HDBresale.csv") %&gt;%
  filter(flat_type == "4 Room") %&gt;%
  filter(month &gt;= "2025-01" & month &lt; "2025-10")

HDBresale$street_name &lt;- gsub("ST\\.", "SAINT", HDBresale$street_name)

glimpse(HDBresale)

